'use client';
import {useRef,useState} from 'react';
import {MomentClip} from '@/components/moment-clip';
import {exportClip} from '@/lib/export-clip';
export default function ReplayQA(){
 const [url,setUrl]=useState(''),[status,setStatus]=useState('Generate a local synthetic recording. No camera or microphone access.'),[results,setResults]=useState<unknown[]>([]);
 const container=useRef<HTMLDivElement>(null),saved=useRef('');
 const delay=(ms:number)=>new Promise(resolve=>setTimeout(resolve,ms));
 async function record(){setStatus('Recording eight seconds of moving graphics and a synthetic tone…');setResults([]);const canvas=document.createElement('canvas');canvas.width=640;canvas.height=360;const ctx=canvas.getContext('2d')!;const ac=new AudioContext();await ac.resume();const audio=ac.createMediaStreamDestination(),osc=ac.createOscillator(),gain=ac.createGain();gain.gain.value=.05;osc.connect(gain).connect(audio);osc.start();let frame=0;
 const paint=()=>{ctx.fillStyle='#214f3e';ctx.fillRect(0,0,640,360);ctx.fillStyle='white';ctx.font='28px sans-serif';ctx.fillText('Synthetic replay · frame '+frame,24,55);ctx.fillRect((frame++*9)%580,170,60,60);};paint();const timer=setInterval(paint,33);const stream=new MediaStream([...canvas.captureStream(30).getVideoTracks(),...audio.stream.getAudioTracks()]);const mime=['video/webm;codecs=vp8,opus','video/webm','video/mp4'].find(t=>MediaRecorder.isTypeSupported(t));const recorder=new MediaRecorder(stream,mime?{mimeType:mime}:undefined);const chunks:BlobPart[]=[];const stopped=new Promise<Blob>(resolve=>{recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=()=>resolve(new Blob(chunks,{type:recorder.mimeType}));});recorder.start(1000);await delay(8100);recorder.stop();const blob=await stopped;clearInterval(timer);osc.stop();stream.getTracks().forEach(t=>t.stop());await ac.close();if(saved.current)URL.revokeObjectURL(saved.current);saved.current=URL.createObjectURL(blob);setUrl(saved.current);setStatus('Recording ready. Test later-clip playback, end replay and export.');}
 async function verify(){setStatus('Checking first play and replay with real MediaRecorder media…');const rows:unknown[]=[];setResults([]);try{const videos=Array.from(container.current!.querySelectorAll('video'));for(let i=0;i<videos.length;i++){const v=videos[i];v.muted=true;for(let run=0;run<2;run++){const initial=v.currentTime,frames=v.getVideoPlaybackQuality().totalVideoFrames;await v.play();await delay(900);const progress=v.currentTime;const decoded=v.getVideoPlaybackQuality().totalVideoFrames-frames;rows.push({clip:i+1,run:run+1,initial,progress,decoded,paused:v.paused,seeking:v.seeking,duration:Number.isFinite(v.duration)?v.duration:'unknown'});setResults([...rows]);await delay(1800);rows.push({clip:i+1,atEnd:v.currentTime,pausedAtEnd:v.paused});}}
 setResults(rows);setStatus('Playback checks complete. Review movement, repeated replay and bounded stops below.');}catch(e){setStatus('Playback test failed: '+(e instanceof Error?e.message:String(e)));setResults(rows);}}
 async function verifyExport(){setStatus('Exporting later range 4–6 seconds…');try{const blob=await exportClip(url,4,6);const ac=new AudioContext();try{const audio=await ac.decodeAudioData(await blob.arrayBuffer());const samples=audio.getChannelData(0);const rms=Math.sqrt(samples.reduce((n,v)=>n+v*v,0)/samples.length);setResults(old=>[...old,{exportBytes:blob.size,audioDuration:audio.duration,rms}]);setStatus('Later-range export decoded with synthetic audio.');}finally{await ac.close();}}catch(e){setStatus('Export failed: '+(e instanceof Error?e.message:String(e)));}}
 return <main style={{padding:32,maxWidth:1100,margin:'auto'}}><h1>Clip replay regression</h1><p role="status">{status}</p><button onClick={()=>void record()}>Generate synthetic recording</button>{url&&<><button onClick={()=>void verify()}>Verify playback twice</button><button onClick={()=>void verifyExport()}>Verify later export</button><div ref={container} style={{display:'grid',gridTemplateColumns:'1fr 1fr',gap:20,marginTop:20}}>{[[4,6],[.1,1.6]].map(([start,end],i)=><MomentClip key={url+i} kind={i===0?'best':'worst'} moment={{id:'qa-'+i,answerIndex:i,start,end,url,mime:'video/webm',transcript:'Fictional transcript for synthetic replay testing.',score:null,reason:'Local synthetic moving-picture and tone fixture.'}}/>)}</div></>}<pre id="replay-results">{JSON.stringify(results,null,2)}</pre></main>;
}
